  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.5rem;
}

.participant-statistics h4 {
  margin: 1.25rem 0 0;
}

.player-match-list,
.participant-career-card {
  margin-top: 1rem;
}

.player-match-card__associations {
  margin: 0.5rem 0 0;
  color: var(--colour-text-secondary);
  line-height: 1.6;
}

.player-match-card__notices {
  margin-top: 1.25rem;
  padding: 1rem;
  border-inline-start: 4px solid var(--colour-brand);
  background: var(--colour-surface-raised);
}

.player-match-card__notices h4,
.player-match-card__notices ul {
  margin: 0;
}

.player-match-card__notices ul {
  margin-top: 0.5rem;
  padding-inline-start: 1.25rem;
}

.statistic-card__source-count,
.statistics-note,
.statistics-section__empty {
  margin-top: 1.25rem;
  line-height: 1.6;
}

.statistics-note {
  padding: 1rem;
  border-left: 3px solid var(--colour-data-accent);
  background: var(--colour-surface-raised);
}

.event-export-controls {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
  gap: 1rem 1.5rem;
  margin-top: 2rem;
  padding: 1.5rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface-raised);
