        </div>
        <p className={`statistics-status statistics-status--${statistics.status}`}>
          {statistics.status === 'complete' ? 'Complete statistics' : 'Partial statistics'}
        </p>
      </div>
      {fixture ? (
        <p className="match-summary__context">
          {fixture.competitionId && fixture.competitionName ? (
            <Link to={`/competitions/${encodeURIComponent(fixture.competitionId)}`}>
              {fixture.competitionName}
            </Link>
          ) : (
            fixture.competitionName ?? 'Competition unavailable'
          )}
          {' · '}
          {fixture.seasonId ? (
            <Link to={`/seasons/${encodeURIComponent(fixture.seasonId)}`}>
              {fixture.seasonLabel}
            </Link>
          ) : (
            fixture.seasonLabel
          )}
          {' · '}
          {fixture.matchType}
        </p>
      ) : null}
      {innings.length > 0 ? (
        <div className="match-summary__scores">
          {innings.map((statistic) => (
            <div key={statistic.statisticId}>
              <Link to={recordPath('competitors', statistic.competitorId)}>
                {statistic.competitorName}
