function SeasonTable({ seasons }: { seasons: ParticipantSeasonAggregate[] }) {
  if (seasons.length === 0) {
    return <p className="statistics-section__empty" role="status">No season aggregates are available.</p>;
  }
  return (
    <DataTable caption="Participant record by season">
      <thead>
        <tr>
          <th scope="col">Season</th><th scope="col">Competition</th>
          <th scope="col" data-numeric>Mat</th><th scope="col" data-numeric>Runs</th>
          <th scope="col" data-numeric>Avg</th><th scope="col" data-numeric>SR</th>
          <th scope="col" data-numeric>HS</th><th scope="col" data-numeric>50s</th>
          <th scope="col" data-numeric>100s</th><th scope="col" data-numeric>Wkts</th>
          <th scope="col" data-numeric>Econ</th>
        </tr>
      </thead>
      <tbody>
        {seasons.map((aggregate) => (
          <tr key={aggregate.statisticId}>
            <th scope="row">{aggregate.seasonId ? <Link to={`/seasons/${encodeURIComponent(aggregate.seasonId)}`}>{aggregate.season}</Link> : aggregate.season}</th>
            <td>{aggregate.competitionId && aggregate.competitionName ? <Link to={`/competitions/${encodeURIComponent(aggregate.competitionId)}`}>{aggregate.competitionName}</Link> : aggregate.competitionName ?? 'Competition unavailable'}</td>
            <td data-numeric>{aggregate.appearances}</td>
            <td data-numeric>{aggregate.batting?.runsScored ?? '—'}</td>
            <td data-numeric>{formatRate(aggregate.batting?.battingAverage ?? null)}</td>
            <td data-numeric>{formatRate(aggregate.batting?.strikeRate ?? null)}</td>
            <td data-numeric>{aggregate.batting ? highestScore(aggregate.batting) : '—'}</td>
            <td data-numeric>{aggregate.batting?.fifties ?? '—'}</td>
            <td data-numeric>{aggregate.batting?.hundreds ?? '—'}</td>
            <td data-numeric>{aggregate.bowling?.wicketsTaken ?? '—'}</td>
            <td data-numeric>{formatRate(aggregate.bowling?.economyRate ?? null)}</td>
          </tr>
        ))}
      </tbody>
    </DataTable>
  );
}

function CompetitionTable({ competitions }: { competitions: ParticipantCompetitionAggregate[] }) {
  if (competitions.length === 0) {
    return <p className="statistics-section__empty" role="status">No competition aggregates are available.</p>;
  }
  return (
    <DataTable caption="Participant record by competition">
      <thead>
        <tr>
          <th scope="col">Competition</th><th scope="col" data-numeric>Mat</th>
          <th scope="col" data-numeric>Runs</th><th scope="col" data-numeric>Avg</th>
          <th scope="col" data-numeric>SR</th><th scope="col" data-numeric>HS</th>
