        </section>
      ) : null}
      {career ? <CareerOverview career={career} /> : (
        <div className="state-message" role="status"><h3>No career record available</h3><p>No career aggregate is published for this player.</p></div>
      )}
      <section aria-labelledby={`${tabsId}-heading`} className="participant-scope-section">
        <div className="statistics-section-heading"><div><p className="eyebrow">Current scope</p><h3 id={`${tabsId}-heading`}>Explore the record</h3></div></div>
        <div className="statistics-tabs" role="tablist" aria-label="Player statistics scope">
          {scopes.map((item) => (
            <button
              aria-controls={`${tabsId}-${item.id}-panel`}
              aria-selected={scope === item.id}
              className="statistics-tab"
              id={`${tabsId}-${item.id}-tab`}
              key={item.id}
              onClick={() => setScope(item.id)}
              role="tab"
              tabIndex={scope === item.id ? 0 : -1}
              type="button"
            >{item.label}</button>
          ))}
        </div>
        <div aria-labelledby={`${tabsId}-${scope}-tab`} className="statistics-tab-panel" id={`${tabsId}-${scope}-panel`} role="tabpanel" tabIndex={0}>
          <p className="scope-description">
            {scope === 'career' ? 'All published standard-innings records.' : scope === 'competition' ? 'Published totals grouped by competition.' : 'Published totals grouped by season and competition.'}
          </p>
          {scope === 'career' ? (career ? <AggregateDetail aggregate={career} /> : <p className="statistics-section__empty">No career aggregate is available.</p>) : null}
          {scope === 'competition' ? <CompetitionTable competitions={competitions} /> : null}
          {scope === 'season' ? <SeasonTable seasons={seasons} /> : null}
        </div>
      </section>
      <section aria-labelledby={`${tabsId}-details-heading`} className="statistics-section calculation-details">
        <div className="statistics-section-heading"><div><p className="eyebrow">Evidence and scope</p><h3 id={`${tabsId}-details-heading`}>Calculation details</h3></div></div>
        <details>
          <summary>How this player record is calculated</summary>
          <p>Aggregates use accepted events from standard innings. Super overs are excluded. Rates are calculated by the backend across the complete selected scope.</p>
          {career ? <p>Career record: {career.appearances} appearances, {career.fixtureCount} batting or bowling matches and {career.sourceEventCount} accepted source events.</p> : null}
        </details>
        <StatisticsDefinitions includeBattingAverage includeBowlingAverage includeBowlingStrikeRate />
      </section>
    </>
  );
}

