import type { AuthChangeEvent, Session } from '@supabase/supabase-js';
import { fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import type { ComponentProps } from 'react';
import { MemoryRouter } from 'react-router-dom';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { PublicApp } from '../../App';
import { AuthProvider } from '../auth/AuthProvider';
import { PlayerPerformance } from './StatisticsPages';

type AuthClient = ComponentProps<typeof AuthProvider>['client'];
type AuthStateListener = (event: AuthChangeEvent, session: Session | null) => void;

const testApiBaseUrl = import.meta.env.VITE_API_BASE_URL ?? 'http://localhost:3000/api/v1';

function response(status: number, body: unknown): Response {
  return {
    ok: status >= 200 && status < 300,
    status,
    json: vi.fn().mockResolvedValue(body),
  } as unknown as Response;
}

function collection(data: unknown[]): Response {
  return response(200, { data, pagination: { nextCursor: null } });
}

// An unrecognised request fails loudly instead of receiving plausible data, so a
// test cannot pass while the request it depends on was never correct.
function notMocked(): Response {
  return response(404, {
    error: { code: 'NOT_FOUND', message: 'Request not mocked in this test.' },
  });
}

function exportDownload(type: string) {
  return { ok: true, status: 200, blob: vi.fn().mockResolvedValue(new Blob(['rows'], { type })) };
}

function traceEvents(count: number) {
  return Array.from({ length: count }, (_, index) => ({
    eventId: `event-${index + 1}`,
    fixtureId: 'fixture-1',
    inningsId: 'innings-1',
    inningsOrdinal: 0,
    sequenceNumber: index + 1,
    strikerParticipantId: 'player-1',
    strikerParticipantName: 'A Player',
    nonStrikerParticipantId: 'non-striker-1',
    nonStrikerParticipantName: 'Non-striker',
    bowlerParticipantId: 'bowler-1',
    bowlerParticipantName: 'Opening Bowler',
    runs: { offBat: 1, extras: 0, total: 1 },
    extras: { wides: null, noBalls: null, byes: null, legByes: null, penalty: null },
    nonBoundary: false,
    bowlerWickets: 0,
    wicketsLost: 0,
  }));
}

function stubDownloads(downloadedFilenames: string[]) {
  vi.stubGlobal('URL', {
    createObjectURL: vi.fn(() => 'blob:event-data'),
    revokeObjectURL: vi.fn(),
  });
  vi.spyOn(HTMLAnchorElement.prototype, 'click').mockImplementation(function (
    this: HTMLAnchorElement,
  ) {
    downloadedFilenames.push(this.download);
  });
}

function createSignedOutAuthClient() {
  return {
    getSession: vi.fn().mockResolvedValue({ data: { session: null } }),
    onAuthStateChange: vi.fn((listener: AuthStateListener) => ({
      data: {
        subscription: {
          id: 'statistics-test-subscription',
          callback: listener,
          unsubscribe: vi.fn(),
        },
      },
    })),
    signInWithOAuth: vi
      .fn()
      .mockResolvedValue({ data: { provider: 'google', url: null }, error: null }),
    signOut: vi.fn().mockResolvedValue({ error: null }),
  } as unknown as AuthClient;
}

function renderRoute(route: string) {
  return render(
    <AuthProvider client={createSignedOutAuthClient()}>
      <MemoryRouter initialEntries={[route]}>
        <PublicApp />
      </MemoryRouter>
    </AuthProvider>,
  );
}

const outcome = {
  kind: 'won',
  winnerCompetitorId: 'team-1',
  winnerCompetitorName: 'Wanderers',
  eliminatorCompetitorId: null,
  eliminatorCompetitorName: null,
  margin: { type: 'wickets', value: 5 },
  method: null,
  decidedByBowlOut: false,
};

const inningsStatistic = {
  statisticId: 'stat-innings-1',
  fixtureId: 'fixture-1',
  scope: 'innings',
  statisticCode: 'team_total',
  inningsId: 'innings-1',
  inningsOrdinal: 0,
  competitorId: 'team-1',
  competitorName: 'Wanderers',
  sourceEventCount: 120,
  metrics: {
    deliveryRuns: 154,
    penaltyRuns: 5,
    totalRuns: 159,
    wicketsLost: 6,
    legalBalls: 120,
    overs: '20.0',
    runRate: 7.95,
    extras: { total: 9, wides: 2, noBalls: 1, byes: 0, legByes: 1, penaltyRuns: 5 },
  },
};

const participantStatistic = {
  statisticId: 'stat-participant-1',
  fixtureId: 'fixture-1',
  scope: 'participant',
  statisticCode: 'participant_fixture',
  participantId: 'player-1',
  participantName: 'A Player',
  competitorId: 'team-1',
  competitorName: 'Wanderers',
  sourceEventCount: 38,
  battingPosition: 3,
  battingParticipation: 'batted' as const,
  dismissal: { status: 'not_out' as const, kind: null, eventId: null },
  batting: { runsScored: 42, ballsFaced: 30, strikeRate: 140, fours: 4, sixes: 2 },
  bowling: {
    runsConceded: 24,
    wides: 0,
    noBalls: 0,
    legalBallsBowled: 18,
    oversBowled: '3.0',
    economyRate: 8,
    wicketsTaken: 2,
  },
};

const unavailableWeather = {
  fixtureId: 'fixture-1',
  date: '2026-08-09',
  availability: 'unavailable',
  reason: 'MISSING_COORDINATES',
  venue: null,
  weather: null,
};

const fixture = {
  fixtureId: 'fixture-1',
  competitionId: 'competition-1',
  competitionName: 'Premier Cricket League',
  seasonId: 'season-1',
  season: '2026',
  seasonLabel: '2026 season',
  competitors: [
    { competitorId: 'team-1', name: 'Wanderers' },
    { competitorId: 'team-2', name: 'Strikers' },
  ],
  matchType: 'T20',
  teamType: 'international',
  gender: 'female',
  ballsPerOver: 6,
  scheduledOvers: 20,
  venue: null,
  toss: null,
  startDate: '2026-08-09',
  endDate: '2026-08-09',
};

const teamNames: Record<string, string> = { 'team-1': 'Wanderers', 'team-2': 'Strikers' };

function inningsFor(competitorId: string, inningsOrdinal: number) {
  return {
    ...inningsStatistic,
    statisticId: `stat-innings-${inningsOrdinal}`,
    inningsId: `innings-${inningsOrdinal}`,
    inningsOrdinal,
    competitorId,
    competitorName: teamNames[competitorId],
  };
}

// A player statistic as the endpoint returns it. A null batting position is a
// player who was selected but did not bat.
function playerStatistic(
  participantId: string,
  participantName: string,
  competitorId: string | null,
  battingPosition: number | null,
) {
  return {
    ...participantStatistic,
    statisticId: `stat-participant-${participantId}`,
    participantId,
    participantName,
    competitorId,
    competitorName: competitorId === null ? null : teamNames[competitorId],
    battingPosition,
    ...(battingPosition === null
      ? { battingParticipation: 'did_not_bat' as const, dismissal: null, batting: null }
      : {}),
  };
}

function renderFixtureStatistics(statistics: unknown[]) {
  vi.stubGlobal(
    'fetch',
    vi.fn().mockImplementation((input: RequestInfo | URL) => {
      const url = String(input);
      if (url.endsWith('/fixtures/fixture-1')) {
        return Promise.resolve(response(200, { data: fixture }));
      }
      if (url.endsWith('/fixtures/fixture-1/weather')) {
        return Promise.resolve(response(200, { data: unavailableWeather }));
      }
      if (url.includes('/participants?')) {
        return Promise.resolve(collection([]));
      }
      if (url.endsWith('/fixtures/fixture-1/statistics')) {
        return Promise.resolve(
          response(200, {
            data: {
              fixtureId: 'fixture-1',
              status: 'complete',
              scope: { superOversIncluded: false },
              outcome,
              highestScorers: [
                {
                  participantId: 'player-1',
                  participantName: 'A Player',
                  competitorId: 'team-1',
                  competitorName: 'Wanderers',
                  inningsId: 'innings-1',
                  inningsOrdinal: 0,
                  runsScored: 42,
                  notOut: true,
                },
              ],
              warnings: [],
              statistics,
            },
          }),
        );
      }
      return Promise.resolve(notMocked());
    }),
  );
  renderRoute('/fixtures/fixture-1');
}

// Every team group in the order it is rendered, with the player named on each of
// its cards in the order those cards are rendered.
async function renderedPlayerGroups() {
  await screen.findByRole('heading', { name: 'Batting scorecard' });
  return screen.getAllByRole('table', { name: /batting scorecard$/ }).map((table) => ({
    team: table.querySelector('caption')?.textContent?.replace(' batting scorecard', ''),
    players: within(table)
      .getAllByRole('rowheader')
      .map((heading) => heading.textContent),
  }));
}

describe('public fixture statistics pages', () => {
  beforeEach(() => {
    window.localStorage.clear();
    vi.stubGlobal(
      'matchMedia',
      vi.fn().mockImplementation((query: string) => ({
        matches: false,
        media: query,
        onchange: null,
        addEventListener: vi.fn(),
        removeEventListener: vi.fn(),
        addListener: vi.fn(),
        removeListener: vi.fn(),
        dispatchEvent: vi.fn(),
      })),
    );
  });

  afterEach(() => {
    vi.restoreAllMocks();
    vi.unstubAllGlobals();
  });

  it('distinguishes a dismissed duck, a not-out duck, dismissal types, and DNB', () => {
    const batting = { runsScored: 0, ballsFaced: 1, strikeRate: 0, fours: 0, sixes: 0 };
    const { rerender } = render(
      <PlayerPerformance
        batting={batting}
        bowling={null}
        battingPosition={3}
        battingParticipation="batted"
        dismissal={{ status: 'dismissed', kind: 'caught', eventId: 'event-1' }}
      />,
    );
    expect(screen.getByText('caught')).toBeInTheDocument();
    expect(screen.queryByLabelText('0 not out')).not.toBeInTheDocument();

    rerender(
      <PlayerPerformance
        batting={batting}
        bowling={null}
        battingPosition={4}
        battingParticipation="batted"
        dismissal={{ status: 'not_out', kind: null, eventId: null }}
      />,
    );
    expect(screen.getByLabelText('0 not out')).toBeInTheDocument();

    rerender(
      <PlayerPerformance
        batting={{ ...batting, runsScored: 12 }}
        bowling={null}
        battingPosition={5}
        battingParticipation="batted"
        dismissal={{ status: 'dismissed', kind: 'bowled', eventId: 'event-2' }}
      />,
    );
    expect(screen.getByText('bowled')).toBeInTheDocument();

    rerender(
      <PlayerPerformance
        batting={{ ...batting, runsScored: 7 }}
        bowling={null}
        battingPosition={6}
        battingParticipation="batted"
        dismissal={{ status: 'dismissed', kind: 'run out', eventId: 'event-3' }}
      />,
    );
    expect(screen.getByText('run out')).toBeInTheDocument();

    rerender(
      <PlayerPerformance
        batting={null}
        bowling={null}
        battingPosition={null}
        battingParticipation="did_not_bat"
        dismissal={null}
      />,
    );
    expect(screen.getByText('Did not bat')).toBeInTheDocument();
    expect(screen.queryByText('Balls faced')).not.toBeInTheDocument();
  });

  it('automatically loads the match overview, statistics, and participating players anonymously', async () => {
    let resolveStatistics!: (value: Response) => void;
    const fetchMock = vi.fn((input: RequestInfo | URL, _init?: RequestInit) => {
      const url = String(input);
      if (url.endsWith('/fixtures/fixture-1')) {
import type {
  ParticipantAggregate,
  ParticipantAggregateBatting,
  ParticipantAggregateBowling,
  ParticipantAggregates,
  ParticipantCareerAggregate,
  ParticipantCompetitionAggregate,
  ParticipantSeasonAggregate,
} from '@sport-analytics/contracts';
import { useId, useState } from 'react';
import { Link } from 'react-router-dom';
import { DataTable } from '../../components/DataTable';
import { StatisticsDefinitions } from './StatisticsDefinitions';

type ParticipantScope = 'career' | 'competition' | 'season';

function formatRate(value: number | null): string | number {
  return value ?? 'â€”';
}

function highestScore(batting: ParticipantAggregateBatting): string {
  return `${batting.highestScore}${batting.highestScoreNotOut ? '*' : ''}`;
}

function bestBowling(bowling: ParticipantAggregateBowling): string {
  return bowling.bestBowling
    ? `${bowling.bestBowling.wicketsTaken}/${bowling.bestBowling.runsConceded}`
    : 'â€”';
}

function Metric({ label, value }: { label: string; value: string | number }) {
  return (
    <div>
      <dt>{label}</dt>
      <dd>{value}</dd>
    </div>
  );
}

function CareerOverview({ career }: { career: ParticipantCareerAggregate }) {
  const headlineMetrics = [
    { label: 'Appearances', value: career.appearances },
    ...(career.batting
      ? [
          { label: 'Runs', value: career.batting.runsScored },
          { label: 'Batting average', value: formatRate(career.batting.battingAverage) },
          { label: 'Strike rate', value: formatRate(career.batting.strikeRate) },
          { label: 'Highest score', value: highestScore(career.batting) },
        ]
      : []),
    ...(career.bowling && career.bowling.innings > 0
      ? [
          { label: 'Wickets', value: career.bowling.wicketsTaken },
          { label: 'Bowling average', value: formatRate(career.bowling.bowlingAverage) },
          { label: 'Economy', value: formatRate(career.bowling.economyRate) },
        ]
      : []),
  ];

  return (
    <section aria-labelledby="career-overview-heading" className="participant-career-overview">
      <div className="statistics-section-heading">
        <div>
          <p className="eyebrow">Career overview</p>
          <h3 id="career-overview-heading">Across all published matches</h3>
        </div>
      </div>
      <dl className="participant-kpis">
        {headlineMetrics.map((metric) => (
          <Metric key={metric.label} {...metric} />
        ))}
      </dl>
      <p className="statistic-card__source-count">
        Based on {career.sourceEventCount} accepted{' '}
        {career.sourceEventCount === 1 ? 'event' : 'events'} from {career.fixtureCount}{' '}
        {career.fixtureCount === 1 ? 'match' : 'matches'} in which this player batted or bowled.
      </p>
    </section>
  );
}

function RecordGroup({
  children,
  empty,
  title,
}: {
  children?: React.ReactNode;
  empty?: string;
  title: string;
}) {
  return (
    <section className="participant-record-group" aria-label={`${title} statistics`}>
      <h4>{title}</h4>
      {children ?? <p className="statistics-section__empty">{empty}</p>}
    </section>
  );
}

function AggregateDetail({ aggregate }: { aggregate: ParticipantAggregate }) {
  return (
    <div className="participant-record-grid">
      <RecordGroup title="Batting" empty="No batting record is available for this scope.">
        {aggregate.batting ? (
          <dl className="record-metrics">
            <Metric label="Innings" value={aggregate.batting.innings} />
            <Metric label="Runs" value={aggregate.batting.runsScored} />
            <Metric label="Balls faced" value={aggregate.batting.ballsFaced} />
            <Metric label="Not outs" value={aggregate.batting.notOuts} />
            <Metric label="Average" value={formatRate(aggregate.batting.battingAverage)} />
            <Metric label="Strike rate" value={formatRate(aggregate.batting.strikeRate)} />
            <Metric label="Highest score" value={highestScore(aggregate.batting)} />
            <Metric label="50s" value={aggregate.batting.fifties} />
            <Metric label="100s" value={aggregate.batting.hundreds} />
            <Metric label="Fours" value={aggregate.batting.fours} />
            <Metric label="Sixes" value={aggregate.batting.sixes} />
          </dl>
        ) : undefined}
      </RecordGroup>
      <RecordGroup title="Bowling" empty="No bowling record is available for this scope.">
        {aggregate.bowling ? (
          <dl className="record-metrics">
            <Metric label="Innings" value={aggregate.bowling.innings} />
            <Metric label="Wickets" value={aggregate.bowling.wicketsTaken} />
            <Metric label="Runs conceded" value={aggregate.bowling.runsConceded} />
            <Metric label="Wides" value={aggregate.bowling.wides} />
            <Metric label="No-balls" value={aggregate.bowling.noBalls} />
            <Metric label="Legal balls" value={aggregate.bowling.legalBallsBowled} />
            <Metric label="Overs" value={aggregate.bowling.oversBowled ?? 'â€”'} />
            <Metric label="Average" value={formatRate(aggregate.bowling.bowlingAverage)} />
            <Metric label="Economy rate" value={formatRate(aggregate.bowling.economyRate)} />
            <Metric label="Strike rate" value={formatRate(aggregate.bowling.bowlingStrikeRate)} />
            <Metric label="Best bowling" value={bestBowling(aggregate.bowling)} />
            <Metric label="4W" value={aggregate.bowling.fourWicketHauls} />
            <Metric label="5W" value={aggregate.bowling.fiveWicketHauls} />
          </dl>
        ) : undefined}
      </RecordGroup>
      <RecordGroup title="Fielding">
        <dl className="record-metrics">
          <Metric label="Catches" value={aggregate.fielding.catches} />
          <Metric label="Stumpings" value={aggregate.fielding.stumpings} />
          <Metric label="Run-out involvements" value={aggregate.fielding.runOutInvolvements} />
        </dl>
      </RecordGroup>
    </div>
  );
}

function SeasonTable({ seasons }: { seasons: ParticipantSeasonAggregate[] }) {
  if (seasons.length === 0) {
    return (
      <p className="statistics-section__empty" role="status">
        No season aggregates are available.
      </p>
    );
  }
  return (
