  background: var(--colour-surface-raised);
}

.player-match-card__notices h4,
.player-match-card__notices ul {
  margin: 0;
}

.player-match-card__notices ul {
  margin-top: 0.5rem;
  padding-inline-start: 1.25rem;
}

.statistic-card__source-count,
.statistics-note,
.statistics-section__empty {
  margin-top: 1.25rem;
  line-height: 1.6;
}

.statistics-note {
  padding: 1rem;
  border-left: 3px solid var(--colour-data-accent);
  background: var(--colour-surface-raised);
}

.match-summary {
  margin-top: var(--space-6);
  padding: var(--space-6);
  border: 1px solid var(--colour-border);
  border-radius: var(--radius-card);
  background: var(--colour-surface);
}

.match-summary__context,
.scope-description {
  margin: var(--space-3) 0 0;
  color: var(--colour-text-secondary);
}

.match-summary__scores {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(13rem, 1fr));
  gap: var(--space-4);
  margin-top: var(--space-5);
  padding-top: var(--space-5);
  border-top: 1px solid var(--colour-border);
}

.match-summary__scores > div {
  display: grid;
  gap: var(--space-1);
}

.match-summary__scores strong {
  font-family: var(--font-display);
  font-size: 2rem;
  font-variant-numeric: tabular-nums;
  line-height: 1;
}

.match-summary__scores span {
  color: var(--colour-text-secondary);
  font-variant-numeric: tabular-nums;
}

.scorecard-section .ui-data-table,
.participant-scope-section .ui-data-table {
  margin-top: var(--space-3);
}

.scorecard-group {
  margin-top: var(--space-5);
}

.scorecard-group h4,
.match-leaders h4,
.participant-record-group h4 {
  margin: 0;
  font-family: var(--font-display);
  font-size: 1.25rem;
}

.scorecard-section .ui-data-table__table,
.participant-scope-section .ui-data-table__table {
  font-variant-numeric: tabular-nums;
}

.scorecard-section .ui-data-table__table th[scope='row'] a {
  white-space: nowrap;
}

.match-leaders__grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-6);
  margin-top: var(--space-5);
}

.match-leaders ol {
  margin: var(--space-3) 0 0;
  padding: 0;
  list-style: none;
}

.match-leaders li {
  display: grid;
  grid-template-columns: 1.5rem minmax(8rem, 1fr) auto minmax(9rem, auto);
  align-items: center;
  gap: var(--space-3);
  padding-block: var(--space-3);
  border-top: 1px solid var(--colour-border);
  font-variant-numeric: tabular-nums;
}

.match-leaders li small {
  display: block;
  margin-top: var(--space-1);
  color: var(--colour-text-muted);
}

.match-leaders__rank {
  color: var(--colour-text-muted);
  font-weight: 700;
}

.calculation-details > details,
.statistics-definitions {
  margin-top: var(--space-4);
  padding: var(--space-4);
  border: 1px solid var(--colour-border);
  border-radius: var(--radius-control);
  background: var(--colour-surface);
}

.calculation-details summary,
.statistics-definitions summary {
  cursor: pointer;
  font-weight: 700;
}

.calculation-details li + li {
  margin-top: var(--space-2);
}

.statistics-definitions dl {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr));
  gap: var(--space-4);
  margin: var(--space-4) 0 0;
}

.statistics-definitions dt {
  font-weight: 700;
}

.statistics-definitions dd {
  margin: var(--space-1) 0 0;
  color: var(--colour-text-secondary);
}

.participant-career-overview,
.participant-scope-section {
  margin-top: var(--space-8);
}

.participant-kpis {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(8rem, 1fr));
  gap: 0;
  margin: var(--space-4) 0 0;
