.ui-data-table {
  max-width: 100%;
  overflow-x: auto;
  border: 1px solid var(--colour-border);
  border-radius: var(--radius-card);
}
.ui-data-table:focus-visible {
  outline: 3px solid var(--colour-focus);
  outline-offset: 3px;
}
.ui-data-table__table {
  width: 100%;
  min-width: 34rem;
  border-collapse: collapse;
  background: var(--colour-surface);
}
.ui-data-table__table caption {
  padding: var(--space-3) var(--space-4);
  color: var(--colour-text-secondary);
  font-size: 0.875rem;
  text-align: left;
}
.ui-data-table__table th,
.ui-data-table__table td {
  padding: var(--space-3) var(--space-4);
  border-top: 1px solid var(--colour-border);
  text-align: left;
}
.ui-data-table__table th {
  background: var(--colour-surface-raised);
  font-size: 0.8125rem;
}
.ui-data-table__table [data-numeric] {
  font-variant-numeric: tabular-nums;
  text-align: right;
}

@media (max-width: 39.9375rem) {
  .ui-page-layout {
    padding-block: var(--space-6) var(--space-12);
  }
  .ui-card {
    padding: var(--space-4);
  }
  .ui-button {
    width: 100%;
  }
}

  font-variant-numeric: tabular-nums;
  line-height: 1;
}

.match-summary__scores span {
  color: var(--colour-text-secondary);
  font-variant-numeric: tabular-nums;
}

.scorecard-section .ui-data-table,
.participant-scope-section .ui-data-table {
  margin-top: var(--space-3);
}

.scorecard-group {
  margin-top: var(--space-5);
}

.scorecard-group h4,
.match-leaders h4,
.participant-record-group h4 {
  margin: 0;
  font-family: var(--font-display);
  font-size: 1.25rem;
}

.scorecard-section .ui-data-table__table,
.participant-scope-section .ui-data-table__table {
  font-variant-numeric: tabular-nums;
}

.scorecard-section .ui-data-table__table th[scope='row'] a {
  white-space: nowrap;
}

.match-leaders__grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-6);
  margin-top: var(--space-5);
}

.match-leaders ol {
  margin: var(--space-3) 0 0;
  padding: 0;

.statistics-definitions dd {
  margin: var(--space-1) 0 0;
  color: var(--colour-text-secondary);
}

.participant-career-overview,
.participant-scope-section {
  margin-top: var(--space-8);
}

.participant-kpis {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(8rem, 1fr));
  gap: 0;
  margin: var(--space-4) 0 0;
  border-block: 1px solid var(--colour-border);
}

.participant-kpis > div {
  padding: var(--space-4);
  border-inline-start: 1px solid var(--colour-border);
}

.participant-kpis dt,
.record-metrics dt {
  color: var(--colour-text-muted);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.participant-kpis dd {
  margin: var(--space-1) 0 0;
  font-family: var(--font-display);
  font-size: 1.75rem;
  font-variant-numeric: tabular-nums;
  font-weight: 700;
}

.statistics-tabs {
  display: flex;
  gap: var(--space-2);
  margin-top: var(--space-5);
  overflow-x: auto;
}

.statistics-tab {
  min-height: 2.75rem;
  padding: var(--space-2) var(--space-4);
  border: 1px solid var(--colour-border);
  border-radius: var(--radius-control);
  background: var(--colour-surface);
  color: var(--colour-text);
  font: inherit;
  font-weight: 700;
  white-space: nowrap;
  cursor: pointer;
}

.statistics-tab[aria-selected='true'] {
  border-color: var(--colour-primary);
  box-shadow: inset 0 -3px 0 var(--colour-primary);
  background: var(--colour-primary-soft);
}

.statistics-tab-panel {
  margin-top: var(--space-4);
}

.participant-record-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-6);
  margin-top: var(--space-5);
}

.participant-record-group {
  padding-top: var(--space-4);
  border-top: 1px solid var(--colour-border);
}

.participant-record-group:last-child {
  grid-column: 1 / -1;
}

.record-metrics {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(7rem, 1fr));
  gap: var(--space-4);
  margin: var(--space-4) 0 0;
}

.record-metrics dd {
  margin: var(--space-1) 0 0;
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-variant-numeric: tabular-nums;
  font-weight: 700;
}

.event-export-controls {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
  gap: 1rem 1.5rem;
  margin-top: 2rem;
  padding: 1.5rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;

