}

.skip-link:focus {
  top: 1rem;
}

.site-header {
  position: relative;
  z-index: 10;
  border-bottom: 1px solid var(--colour-border);
  background: var(--colour-surface);
  box-shadow: var(--shadow-header);
}

.site-header__inner,
.site-footer__inner,
.content-boundary {
  width: min(100% - 3rem, 100rem);
  margin-inline: auto;
}

.site-header__inner {
  min-height: 5.5rem;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 1.5rem;
}

.site-header__controls,
.auth-navigation,
.auth-navigation-wrap {
  display: flex;
  align-items: center;
}
  height: 1.25rem;
  margin: 0.125rem 0 0;
  accent-color: var(--colour-primary);
}

.correction-wickets-field textarea {
  min-height: 10rem;
}

.correction-form > .button {
  justify-self: start;
}

.correction-workspace > .submission-result,
.correction-workspace > div > .submission-result,
.correction-workspace > .state-message,
.correction-workspace > .fixture-statistics-overview {
  margin-top: 2rem;
}

.eyebrow {
  margin: 0 0 1rem;
  color: var(--colour-label);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
}

h1,
h2,
h3,
p {
  overflow-wrap: anywhere;
}

  gap: 0.75rem;
  justify-content: flex-end;
  padding-top: 1.5rem;
}

.pagination__status {
  margin: 0;
  color: var(--colour-text-muted);
  font-size: 0.875rem;
  white-space: nowrap;
}

.pagination__end {
  margin: 1.5rem 0 0;
  color: var(--colour-text-muted);
  font-size: 0.875rem;
  text-align: right;
}

.detail-page {
  min-height: 38rem;
  padding-block: 2rem 5rem;
}

.page-heading--detail {
  padding-block: 1rem;
  border-bottom: 2px solid var(--colour-primary);
}

.record-facts {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0 2rem;
  margin: 0;
}

.record-facts > div {
  min-width: 0;
  padding-block: 1rem;
  border-bottom: 1px solid var(--colour-border);
}

.record-facts dt {
  color: var(--colour-text-muted);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.record-facts dd {
  margin: 0.5rem 0 0;
  overflow-wrap: anywhere;
  font-family: var(--font-display);
  font-size: 1.375rem;
  font-weight: 700;
}

.related-records {
  margin-top: 2rem;
}

.related-collection {
  margin-top: 2rem;
}

.fixture-weather {
