.record-facts dd {
  margin: 0.5rem 0 0;
  overflow-wrap: anywhere;
  font-family: var(--font-display);
  font-size: 1.375rem;
  font-weight: 700;
}

.related-records {
  margin-top: 2rem;
}

.related-collection {
  margin-top: 2rem;
}

.fixture-weather {
  margin-top: 2rem;
  padding: 1.5rem;
  border: 1px solid var(--colour-border);
  border-left: 3px solid var(--colour-data-accent);
  border-radius: var(--radius-card);
  background: var(--colour-surface-soft);
}

.fixture-weather__heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.fixture-weather h2,
.fixture-weather__heading p,
.fixture-weather__state {
  margin: 0;
}

.fixture-weather h2 {
  font-size: 1.5rem;
}

.fixture-weather__heading p,
.fixture-weather__state {
  color: var(--colour-text-secondary);
}

.release-schema > dl > div {
  padding-block: 1rem;
  border-bottom: 1px solid var(--colour-border);
}

.release-schema dd {
  margin: 0.5rem 0 0;
  color: var(--colour-text-secondary);
  line-height: 1.5;
}

.statistics-summary,
.statistics-section {
  margin-top: 2rem;
}

.statistics-section-heading,
.statistic-card__heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1.5rem;
}

.statistics-section-heading {
  padding-bottom: 1rem;
  border-bottom: 2px solid var(--colour-primary);
}

.statistics-section-heading h2,
.statistics-section-heading h3,
.statistics-warnings h3,
.statistics-warnings h2 {
  max-width: none;
  margin: 0;
  font-size: 1.5rem;
}

.statistics-section-heading > p,
.statistics-section-heading > div > p,
.statistics-card__heading p,
.statistic-card__source-count,
.statistics-note,
.statistics-section__empty {
  color: var(--colour-text-secondary);
}

.statistics-section-heading > p,
.statistics-section-heading > div > p,
.statistic-card__heading p,
.statistic-card__source-count,
.statistics-note,
.statistics-section__empty {
  margin: 0;
}

.statistics-status {
  padding: 0.35rem 0.6rem;
  border: 1px solid var(--colour-border);
  border-radius: 999px;
  background: var(--colour-surface-raised);
  color: var(--colour-text);
  font-size: 0.8125rem;
  font-weight: 750;
  white-space: nowrap;
}

.statistics-status--partial {
  border-color: var(--colour-brand);
}

.statistics-warnings {
  margin-top: 2rem;
  padding: 1.5rem;
  border-left: 3px solid var(--colour-brand);
  background: var(--colour-surface-raised);
}

.statistics-warnings ul {
    flex-direction: column;
  }

  .filter-grid,
  .record-facts,
  .release-list dl,
  .release-schema > dl {
    grid-template-columns: 1fr;
  }

  .record-list__item {
    grid-template-columns: 1fr;
    gap: 0.5rem;
    padding-block: 1.25rem;
  }

  .record-list__summary {
    grid-column: auto;
  }

  .statistics-section-heading,
  .statistic-card__heading,
  .participant-statistics {
    grid-template-columns: 1fr;
    flex-direction: column;
  }

  .fixture-weather__heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .fixture-weather__facts {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .event-export-controls {
    grid-template-columns: 1fr;
    align-items: stretch;
  }

  .event-export-controls__actions,
  .event-export-controls__actions .button {
    width: 100%;
  }

  .statistic-card,
  .event-trace,
  .statistics-warnings {
    padding: 1.25rem;
  }

  .statistic-metrics,
  .event-trace dl {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .match-summary,
  .calculation-details > details,
  .statistics-definitions,
  .innings-extras {
    padding: var(--space-4);
  }

  .match-leaders__grid,
  .participant-record-grid {
    grid-template-columns: 1fr;
  }

  .match-leaders li {
    grid-template-columns: 1.25rem minmax(0, 1fr) auto;
  }

  .match-leaders li > span:last-child {
    grid-column: 2 / -1;
  }

  .participant-record-group:last-child {
    grid-column: auto;
  }

  .participant-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .pagination,
  .pagination .button {
    width: 100%;
  }

  .pagination__end {
    text-align: left;
  }

  .detail-page {
    padding-block: 1.5rem 3.5rem;
  }

  .admin-release-page {
    padding-bottom: 3.5rem;
  }

  .admin-release-warning,
  .admin-release-form,
  .admin-release-feedback {
    margin-inline: -0.75rem;
    padding: 1.25rem 0.75rem;
    border-right: 0;
    border-left: 0;
    border-radius: 0;

