} from '@sport-analytics/contracts';
import { expect, test, type Page } from '@playwright/test';

const competitors = [
  { competitorId: 'team-1', name: 'Wanderers' },
  { competitorId: 'team-2', name: 'Strikers' },
];

const fixture = {
  fixtureId: 'fixture-1',
