    expect(
      requestedUrls.some((url) => url.includes('/participants/player-1/fixtures?limit=10')),
    ).toBe(true);
    expect(requestedUrls.some((url) => url.endsWith('/participants/player-1/statistics'))).toBe(
      true,
    );

    const internalValues = [
      'stat-career-1',
